            expr_free(a, out);
            rest.iter().for_each(|(_, x)| expr_free(x, out))
        }
        Ex::IfExp(a, b, c) => {
            expr_free(a, out);
            expr_free(b, out);
            expr_free(c, out)
        }
        Ex::FStr(parts) => {
            for p in parts {
                if let FPart::Expr(x, _, spec, _) = p {
                    expr_free(x, out);
                    for sp in spec {
                        if let FPart::Expr(y, ..) = sp {
                            expr_free(y, out);
                        }
                    }
                }
            }
        }
        _ => {}
    }
