            for n in inner {
                if !ps.contains(&n) {
                    out.insert(n);
                }
            }
        }
        Ex::Comp(_, elt, val, gens) => {
            let mut inner = BTreeSet::new();
            expr_free(elt, &mut inner);
            if let Some(v) = val {
                expr_free(v, &mut inner);
            }
            for g in gens {
                expr_free(&g.iter, &mut inner);
                g.ifs.iter().for_each(|x| expr_free(x, &mut inner));
            }
