            if let Some(x) = x {
                expr_free(x, out)
            }
        }
        Ex::Index(a, b) | Ex::Bin(_, a, b) | Ex::And(a, b) | Ex::Or(a, b) => {
            expr_free(a, out);
            expr_free(b, out)
